        for(int i=0;i<files.length();i++){JSONObject file=files.getJSONObject(i);String path=path(file.getString("path"));long size=integer(file,"bytes",0,MAX_FILE_BYTES);if(!file.getString("sha256").matches("[a-f0-9]{64}")||!(file.opt("executable") instanceof Boolean)||bases.put(path,file)!=null)throw new SecurityException("原包文件重复或hash/模式不完整");total=Math.addExact(total,size);}
