        for(int i=0;i<selected.length();i++){JSONObject file=selected.getJSONObject(i);String path=path(file.getString("path"));JSONObject base=bases.get(path);long version=integer(file,"baseVersion",0,Integer.MAX_VALUE);String hash=base==null?"absent":base.getString("sha256");if(file.length()!=3||!chosen.add(path)||!hash.equals(file.getString("baseHash")))throw new SecurityException("原手机写路径base/hash/version与固定包不同");}
